//! The exported CPython 3.15 (free-threaded) C API.
//!
//! One file per header area; every entry point is
//! `#[unsafe(no_mangle)] pub unsafe extern "C" fn Py...`. The functions are thin
//! adapters over the Rust runtime (`abstract_`, `types::*`), converting between the
//! C conventions (NULL / -1 + exception set, borrowed vs. new references) and
//! `PyResult`. `declared.txt` is the inventory of every PyAPI_FUNC/PyAPI_DATA in
//! spec/Include (generated by tools/capi_inventory.sh).
#![allow(non_snake_case, non_upper_case_globals, clippy::missing_safety_doc, unused_unsafe)]

