use crate::errors::*;
use crate::ffi::*;
use crate::object::*;
use std::ffi::{CStr, c_char, c_int};

/// Borrow a non-null object pointer.
#[inline(always)]
pub(crate) unsafe fn r<'a>(p: *mut PyObject) -> &'a PyObject {
    unsafe { &*p }
}

/// Borrow a possibly-null object pointer.
#[inline(always)]
pub(crate) unsafe fn opt<'a>(p: *mut PyObject) -> Option<&'a PyObject> {
    if p.is_null() { None } else { Some(unsafe { &*p }) }
}

/// New reference -> C.
#[inline(always)]
pub(crate) fn ret(r: PyResult) -> *mut PyObject {
    into_c(r)
}

/// Optional new reference -> C (None => NULL without exception).
#[inline(always)]
pub(crate) fn ret_opt(r: Option<PyRef>) -> *mut PyObject {
    match r {
        Some(o) => o.into_raw(),
        None => std::ptr::null_mut(),
    }
}

#[inline(always)]
pub(crate) fn ret_i(r: PyResult<()>) -> c_int {
    int_into_c(r)
}

#[inline(always)]
pub(crate) fn ret_b(r: PyResult<bool>) -> c_int {
    match r {
        Ok(true) => 1,
        Ok(false) => 0,
        Err(_) => -1,
    }
}

#[inline(always)]
pub(crate) fn ret_n(r: PyResult<usize>) -> Py_ssize_t {
    match r {
        Ok(n) => n as Py_ssize_t,
        Err(_) => -1,
    }
}

/// C string -> &str (lossy for invalid UTF-8; C API strings are UTF-8 by contract).
pub(crate) unsafe fn cs<'a>(p: *const c_char) -> std::borrow::Cow<'a, str> {
    if p.is_null() {
        return std::borrow::Cow::Borrowed("");
    }
    unsafe { CStr::from_ptr(p).to_string_lossy() }
}

/// C string -> new str object (UTF-8 decoding with surrogateescape-free strict semantics).
pub(crate) unsafe fn cstr_obj(p: *const c_char) -> PyResult {
    unsafe {
        let b = CStr::from_ptr(p).to_bytes();
        crate::capi::unicode::decode_utf8(b, None)
    }
}

/// Raise SystemError("bad argument to internal function").
pub(crate) fn bad_internal() -> PyErr {
    system_error("bad argument to internal function")
}

/// Raise SystemError if `p` is NULL; borrow it otherwise.
#[inline]
pub(crate) unsafe fn nn<'a>(p: *mut PyObject) -> PyResult<&'a PyObject> {
    if p.is_null() {
        if !err_occurred() {
            return Err(system_error("null argument to internal routine"));
        }
        return Err(PyErr);
    }
    Ok(unsafe { &*p })
}

/// Allocate a NUL-terminated copy of `s` with PyMem_Malloc (caller frees with PyMem_Free).
pub(crate) fn pymem_cstring(s: &[u8]) -> *mut c_char {
    unsafe {
        let p = crate::capi::mem::PyMem_Malloc(s.len() + 1) as *mut u8;
        if p.is_null() {
            return std::ptr::null_mut();
        }
        std::ptr::copy_nonoverlapping(s.as_ptr(), p, s.len());
        *p.add(s.len()) = 0;
        p as *mut c_char
    }
}

/// A leaked NUL-terminated copy (for names stored in type objects etc.).
pub(crate) fn leak_cstring(s: &str) -> *const c_char {
    let mut v = s.as_bytes().to_vec();
    v.push(0);
    Box::leak(v.into_boxed_slice()).as_ptr() as *const c_char
}

pub(crate) fn tname(o: &PyObject) -> String {
    crate::types::typeobject::type_name(o.ty())
}

/// The list of declared C API symbols (name kind flags).
pub const DECLARED: &str = include_str!("declared.txt");
